452	+const MIGRATION_LOCK = 727001;
453	+
454	+export function createPool(connectionString: string, max?: number): pg.Pool {
455	+  const pool = new pg.Pool({ connectionString, max });
456	+  pool.on('error', (err: Error & { code?: string }) => {
457	+    // 57P01: the server ended an idle connection, as a test teardown's `drop database ... with (force)` does.
458	+    if (err.code !== '57P01') console.error('postgres pool error', err);
459	+  });
460	+  return pool;
461	+}
