463	+export async function migrate(pool: pg.Pool): Promise<string[]> {
464	+  const dir = new URL('../../migrations/', import.meta.url);
465	+  const client = await pool.connect();
466	+  try {
467	+    await client.query('select pg_advisory_lock($1)', [MIGRATION_LOCK]);
468	+    await client.query(
469	+      'create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now())',
470	+    );
471	+    const done = new Set((await client.query('select name from schema_migrations')).rows.map((r) => r.name));
472	+    const applied: string[] = [];
473	+    for (const name of (await readdir(dir)).filter((f) => f.endsWith('.sql')).sort()) {
474	+      if (done.has(name)) continue;
475	+      const sql = await readFile(new URL(name, dir), 'utf8');
476	+      try {
477	+        await client.query('begin');
478	+        await client.query(sql);
479	+        await client.query('insert into schema_migrations (name) values ($1)', [name]);
480	+        await client.query('commit');
481	+      } catch (err) {
482	+        await client.query('rollback');
483	+        throw err;
484	+      }
485	+      applied.push(name);
486	+    }
487	+    return applied;
488	+  } finally {
489	+    try {
490	+      await client.query('select pg_advisory_unlock($1)', [MIGRATION_LOCK]);
491	+    } finally {
492	+      client.release();
493	+    }
494	+  }
495	+}
