511	+export async function createTestDb(): Promise<TestDb> {
512	+  const adminUrl = process.env.DATABASE_URL ?? 'postgres://bookings:bookings@localhost:5433/bookings';
513	+  const name = `t_${hex()}`;
514	+  const admin = createPool(adminUrl, 1);
515	+  await admin.query(`create database "${name}"`);
516	+  const url = new URL(adminUrl);
517	+  url.pathname = `/${name}`;
518	+  const pool = createPool(url.toString(), 40); // 40 connections for the race tests
519	+  const drop = async () => {
520	+    await pool.end();
521	+    await admin.query(`drop database "${name}" with (force)`);
522	+    await admin.end();
523	+  };
524	+  try {
525	+    await migrate(pool);
526	+  } catch (err) {
527	+    await drop();
528	+    throw err;
529	+  }
530	+  return { pool, drop };
